import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class Solution {
    record Resultado(int moedas, List<Integer> combinacao) {}

    static Resultado troco(int[] moedas, int alvo) {
        if (alvo < 0) throw new IllegalArgumentException("alvo negativo");
        for (int m : moedas) {
            if (m <= 0) throw new IllegalArgumentException("moeda invalida: " + m);
        }

        int infinito = alvo + 1;
        int[] dp = new int[alvo + 1];
        int[] escolha = new int[alvo + 1];
        Arrays.fill(dp, infinito);
        dp[0] = 0;

        for (int valor = 1; valor <= alvo; valor++) {
            for (int moeda : moedas) {
                if (moeda <= valor && dp[valor - moeda] + 1 < dp[valor]) {
                    dp[valor] = dp[valor - moeda] + 1;
                    escolha[valor] = moeda;
                }
            }
        }

        if (dp[alvo] == infinito) return new Resultado(-1, List.of());

        var combinacao = new ArrayList<Integer>();
        for (int valor = alvo; valor > 0; valor -= escolha[valor]) {
            combinacao.add(escolha[valor]);
        }
        combinacao.sort(Integer::compareTo);
        return new Resultado(dp[alvo], List.copyOf(combinacao));
    }
}

