import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class SolutionTest {
    @Test void trocoPossivel() {
        var r = Solution.troco(new int[]{1,2,5}, 11);
        assertEquals(3, r.moedas());
        assertEquals(3, r.combinacao().size());
        assertEquals(11, r.combinacao().stream().mapToInt(Integer::intValue).sum());
        assertTrue(r.combinacao().stream().allMatch(m -> m == 1 || m == 2 || m == 5));
    }

    @Test void impossivel() {
        var r = Solution.troco(new int[]{2}, 3);
        assertEquals(-1, r.moedas());
        assertTrue(r.combinacao().isEmpty());
    }

    @Test void alvoZero() {
        var r = Solution.troco(new int[]{1,5}, 0);
        assertEquals(0, r.moedas());
        assertTrue(r.combinacao().isEmpty());
    }

    @Test void combinacaoEhCrescente() {
        var c = Solution.troco(new int[]{1,3,4}, 6).combinacao();
        for (int i = 1; i < c.size(); i++) assertTrue(c.get(i - 1) <= c.get(i));
    }

    @Test void entradasInvalidas() {
        assertThrows(IllegalArgumentException.class, () -> Solution.troco(new int[]{1,0}, 5));
        assertThrows(IllegalArgumentException.class, () -> Solution.troco(new int[]{1}, -1));
    }
}
